<script setup lang="ts">
import Swal from 'sweetalert2'
import type { FinanceBillingEventSummary, FinanceBillingPolicySummary, FinanceBillingRegister, FinanceFeeCatalogueRegister } from '@emhare/portal-shell/types/finance'

definePageMeta({ layout: 'dashboard' })
const api = useEmhareApi();const toast = useToast();const { showError } = useEmhareConfirm()
const register = ref<FinanceBillingRegister>({ billingPolicies: [], billingEvents: [], invoices: [] })
const catalogues = ref<FinanceFeeCatalogueRegister>({ catalogues: [] });const loading = ref(false);const operatingId = ref<string | null>(null)
const activeDataset = ref('events')
const selectedEventIds = ref<string[]>([]);const policyModalOpen = ref(false);const invoiceModalOpen = ref(false)
const policyForm = reactive({ code: '', name: '', sourceEventType: 'student-records.registration-confirmed.v1', feeCatalogueId: '', lineBasis: 'REGISTRATION', quantityBasis: 'FIXED', fixedQuantity: 1, effectiveFrom: '', effectiveUntil: '' })
const invoiceForm = reactive({ invoiceDate: today(), dueDate: today(30), postingReason: '' })
const counts = computed(() => ({ pending: register.value.billingEvents.filter(item => item.status === 'PENDING_APPROVAL').length, approved: register.value.billingEvents.filter(item => item.status === 'APPROVED').length, invoiced: register.value.billingEvents.filter(item => item.status === 'INVOICED').length, invoices: register.value.invoices.length, activePolicies: register.value.billingPolicies.filter(item => item.status === 'ACTIVE').length }))
const approvedEvents = computed(() => register.value.billingEvents.filter(item => item.status === 'APPROVED'))
const selectedEvents = computed(() => approvedEvents.value.filter(item => selectedEventIds.value.includes(item.id)))
const selectionCompatible = computed(() => !selectedEvents.value.length || selectedEvents.value.every(item => item.studentFinanceAccountId === selectedEvents.value[0]?.studentFinanceAccountId && item.transactionCurrencyCode === selectedEvents.value[0]?.transactionCurrencyCode))
const selectedTotal = computed(() => selectedEvents.value.reduce((sum, item) => sum + item.transactionAmount, 0))
const catalogueItems = computed(() => catalogues.value.catalogues.filter(item => item.status === 'ACTIVE').map(item => ({ label: `${item.code} · ${item.name}`, value: item.id })))
const lineBasisItems = [{ label: 'One charge per registration', value: 'REGISTRATION' }, { label: 'One charge per registered Module', value: 'REGISTERED_MODULE' }]
const quantityBasisItems = [{ label: 'Fixed quantity', value: 'FIXED' }, { label: 'Module credit value', value: 'MODULE_CREDIT' }]
const datasets = computed(() => [
  { label: 'Billing events', value: 'events', icon: 'i-lucide-receipt-text', badge: register.value.billingEvents.length },
  { label: 'Billing policies', value: 'policies', icon: 'i-lucide-git-branch', badge: register.value.billingPolicies.length },
  { label: 'Invoices', value: 'invoices', icon: 'i-lucide-file-check-2', badge: register.value.invoices.length }
])

onMounted(load)
async function load(){loading.value=true;try{[register.value,catalogues.value]=await Promise.all([api.request<FinanceBillingRegister>('/api/finance/billing'),api.request<FinanceFeeCatalogueRegister>('/api/finance/fee-catalogues')]);selectedEventIds.value=selectedEventIds.value.filter(id=>approvedEvents.value.some(item=>item.id===id))}catch(error){await showError('Billing workspace could not be loaded',api.errorMessage(error))}finally{loading.value=false}}
async function decideEvent(event:FinanceBillingEventSummary,action:'approve'|'reject'){const approving=action==='approve';const result=await Swal.fire({title:approving?'Approve billing event?':'Reject billing event?',text:approving?'Confirm the authoritative source, student account, approved price, quantity, and USD base amount.':'The source evidence remains immutable. A corrected source line must create a new event.',input:'textarea',inputLabel:approving?'Independent approval evidence':'Rejection reason',showCancelButton:true,confirmButtonText:approving?'Approve charge':'Reject charge',confirmButtonColor:approving?'#006633':'#b42318',inputValidator:value=>value.trim()?undefined:'A complete reason is required.'});if(!result.isConfirmed||!result.value?.trim())return;await perform(event.id,()=>api.request(`/api/finance/billing/events/${event.id}/${action}`,{method:'POST',body:{reason:result.value.trim(),expectedVersion:event.version}}),approving?'Billing event approved':'Billing event rejected')}
function toggleEvent(event:FinanceBillingEventSummary){selectedEventIds.value=selectedEventIds.value.includes(event.id)?selectedEventIds.value.filter(id=>id!==event.id):[...selectedEventIds.value,event.id]}
function openInvoice(){if(!selectedEvents.value.length||!selectionCompatible.value)return;Object.assign(invoiceForm,{invoiceDate:today(),dueDate:today(30),postingReason:''});invoiceModalOpen.value=true}
async function postInvoice(){if(!selectedEvents.value.length||!invoiceForm.postingReason.trim())return;operatingId.value='invoice';try{await api.request('/api/finance/billing/invoices',{method:'POST',body:{billingEventIds:selectedEventIds.value,invoiceDate:invoiceForm.invoiceDate,dueDate:invoiceForm.dueDate,postingReason:invoiceForm.postingReason.trim()}});invoiceModalOpen.value=false;selectedEventIds.value=[];await load();toast.add({title:'Invoice posted',description:'Approved charge evidence was copied into an immutable receivable document.',color:'success'})}catch(error){await showError('Invoice could not be posted',api.errorMessage(error))}finally{operatingId.value=null}}
function openPolicy(){Object.assign(policyForm,{code:'',name:'',sourceEventType:'student-records.registration-confirmed.v1',feeCatalogueId:catalogueItems.value[0]?.value??'',lineBasis:'REGISTRATION',quantityBasis:'FIXED',fixedQuantity:1,effectiveFrom:'',effectiveUntil:''});policyModalOpen.value=true}
async function createPolicy(){if(!policyForm.code.trim()||!policyForm.name.trim()||!policyForm.feeCatalogueId||!policyForm.effectiveFrom)return;operatingId.value='policy';try{await api.request('/api/finance/billing/policies',{method:'POST',body:{...policyForm,code:policyForm.code.trim(),name:policyForm.name.trim(),fixedQuantity:policyForm.quantityBasis==='FIXED'?policyForm.fixedQuantity:null,effectiveFrom:new Date(policyForm.effectiveFrom).toISOString(),effectiveUntil:policyForm.effectiveUntil?new Date(policyForm.effectiveUntil).toISOString():null}});policyModalOpen.value=false;await load();toast.add({title:'Draft billing policy created',color:'success'})}catch(error){await showError('Billing policy could not be created',api.errorMessage(error))}finally{operatingId.value=null}}
async function movePolicy(policy:FinanceBillingPolicySummary,action:'activate'|'retire'){const result=await Swal.fire({title:action==='activate'?'Activate billing policy?':'Retire billing policy?',text:action==='activate'?'A different Finance operator must confirm the source event, line basis, quantity basis, fee definition, and effectivity.':'New source events will stop selecting this version; prior charges remain unchanged.',input:'textarea',inputLabel:action==='activate'?'Independent activation evidence':'Retirement reason',showCancelButton:true,confirmButtonText:action==='activate'?'Activate policy':'Retire policy',confirmButtonColor:'#006633',inputValidator:value=>value.trim()?undefined:'A complete reason is required.'});if(!result.isConfirmed||!result.value?.trim())return;await perform(policy.id,()=>api.request(`/api/finance/billing/policies/${policy.id}/${action}`,{method:'POST',body:{reason:result.value.trim(),expectedVersion:policy.version}}),action==='activate'?'Billing policy activated':'Billing policy retired')}
async function perform(id:string,action:()=>Promise<unknown>,title:string){operatingId.value=id;try{await action();await load();toast.add({title,color:'success'})}catch(error){await showError('Billing operation could not be completed',api.errorMessage(error))}finally{operatingId.value=null}}
function today(offset=0){const value=new Date();value.setDate(value.getDate()+offset);return value.toISOString().slice(0,10)}
function money(value:number,currency='USD'){return new Intl.NumberFormat('en-ZW',{style:'currency',currency}).format(value)}
function date(value:string){return new Intl.DateTimeFormat('en-ZW',{dateStyle:'medium'}).format(new Date(value))}
function title(value:string){return value.toLowerCase().split('_').map(word=>word.charAt(0).toUpperCase()+word.slice(1)).join(' ')}
function statusColour(status:string){return ['APPROVED','INVOICED','ACTIVE','POSTED'].includes(status)?'success':status.includes('PENDING')||status==='DRAFT'?'warning':status==='REJECTED'?'error':'neutral'}
</script>

<template>
  <UDashboardPanel>
    <template #header><UDashboardNavbar title="Billing and invoice control"><template #leading><UDashboardSidebarCollapse /></template><template #right><UButton label="Refresh" icon="i-lucide-refresh-cw" color="neutral" variant="outline" :loading="loading" @click="load" /></template></UDashboardNavbar></template>
    <template #body><div class="space-y-5 p-4 sm:p-6">
      <UAlert color="primary" variant="soft" icon="i-lucide-receipt-text" title="Approved charges become immutable invoices" description="Registration and other authoritative events are priced by Finance-owned policies. A different operator approves each charge before a posting operator can assemble the invoice." />
      <section class="grid gap-3 sm:grid-cols-2 xl:grid-cols-5"><UCard v-for="item in [{label:'Awaiting approval',value:counts.pending,tone:'text-warning'},{label:'Approved to post',value:counts.approved,tone:'text-primary'},{label:'Invoiced events',value:counts.invoiced,tone:'text-success'},{label:'Posted invoices',value:counts.invoices,tone:'text-success'},{label:'Active policies',value:counts.activePolicies,tone:'text-primary'}]" :key="item.label" :ui="{body:'p-4'}"><p class="text-xs uppercase text-muted">{{ item.label }}</p><p class="mt-2 text-2xl font-semibold" :class="item.tone">{{ item.value }}</p></UCard></section>

      <UTabs v-model="activeDataset" :items="datasets" :content="false" color="primary" variant="pill" />

      <UCard v-if="activeDataset==='events'" :ui="{body:'p-0'}"><div class="flex flex-wrap items-center justify-between gap-3 border-b border-muted p-4"><div><p class="text-xs uppercase text-primary">Charge approval queue</p><h2 class="mt-1 text-lg font-semibold">Billing events</h2></div><div class="flex items-center gap-3"><p v-if="selectedEvents.length" class="text-sm text-muted">{{ selectedEvents.length }} selected · {{ money(selectedTotal, selectedEvents[0]?.transactionCurrencyCode) }}</p><EmhareGuidedActionButton label="Post selected invoice" icon="i-lucide-file-check-2" guidance-title="Invoice selection is not ready" :guidance-instructions="!selectedEvents.length ? ['Select at least one approved billing event.'] : !selectionCompatible ? ['Select billing events for one student finance account and one transaction currency only.'] : []" @click="openInvoice" /></div></div><UAlert v-if="selectedEvents.length && !selectionCompatible" color="error" variant="soft" title="Selection cannot be posted together" description="One invoice must contain one student finance account and one transaction currency." class="m-4" /><EmharePaginatedCollection v-slot="{ items: paginatedBillingEvents }" :items="register.billingEvents"><div class="overflow-x-auto"><table class="w-full min-w-[1180px] text-left text-sm"><thead class="bg-muted/40 text-xs uppercase text-muted"><tr><th class="px-4 py-3">Select</th><th class="px-4 py-3">Event and source</th><th class="px-4 py-3">Student account</th><th class="px-4 py-3">Charge</th><th class="px-4 py-3">Transaction</th><th class="px-4 py-3">USD base</th><th class="px-4 py-3">State</th><th class="px-4 py-3 text-right">Action</th></tr></thead><tbody><tr v-for="event in paginatedBillingEvents" :key="event.id" class="border-t border-muted"><td class="px-4 py-3"><UCheckbox v-if="event.status==='APPROVED'" :model-value="selectedEventIds.includes(event.id)" :aria-label="`Select ${event.eventNumber}`" @update:model-value="toggleEvent(event)" /></td><td class="px-4 py-3"><p class="font-mono text-xs text-primary">{{ event.eventNumber }}</p><p class="mt-1 font-medium">{{ event.description }}</p><p class="mt-1 text-xs text-muted">{{ event.sourceService }} · {{ event.sourceLineReference }}</p></td><td class="px-4 py-3"><p class="font-medium">{{ event.studentNumber }}</p><p class="text-xs text-muted">{{ event.accountNumber }}</p></td><td class="px-4 py-3"><p>{{ event.feeCode }} · v{{ event.feeRuleVersion }}</p><p class="text-xs text-muted">Quantity {{ event.quantity }}</p></td><td class="px-4 py-3 font-medium">{{ money(event.transactionAmount,event.transactionCurrencyCode) }}</td><td class="px-4 py-3 font-medium text-success">{{ money(event.baseAmount) }}</td><td class="px-4 py-3"><UBadge :label="title(event.status)" :color="statusColour(event.status)" variant="subtle" /></td><td class="px-4 py-3"><div v-if="event.status==='PENDING_APPROVAL'" class="flex justify-end gap-2"><UButton label="Approve" size="xs" :loading="operatingId===event.id" @click="decideEvent(event,'approve')" /><UButton label="Reject" size="xs" color="error" variant="outline" @click="decideEvent(event,'reject')" /></div><p v-else class="text-right text-xs text-muted">{{ date(event.effectiveAt) }}</p></td></tr><tr v-if="!register.billingEvents.length"><td colspan="8" class="px-4 py-8 text-center text-muted">No billing events have reached Finance.</td></tr></tbody></table></div></EmharePaginatedCollection></UCard>

      <UCard v-if="activeDataset==='policies'" :ui="{body:'p-0'}"><div class="flex items-center justify-between gap-3 border-b border-muted p-4"><div><p class="text-xs uppercase text-primary">Automated charging</p><h2 class="mt-1 text-lg font-semibold">Billing policies</h2></div><UButton label="Create billing policy" icon="i-lucide-plus" color="primary" @click="openPolicy" /></div><EmharePaginatedCollection v-slot="{ items: paginatedPolicies }" :items="register.billingPolicies"><div class="divide-y divide-muted"><div v-for="policy in paginatedPolicies" :key="policy.id" class="flex items-start justify-between gap-4 p-4"><div><div class="flex items-center gap-2"><p class="font-mono text-xs text-primary">{{ policy.code }} · v{{ policy.policyVersion }}</p><UBadge :label="policy.status" :color="statusColour(policy.status)" variant="subtle" /></div><p class="mt-1 font-medium">{{ policy.name }}</p><p class="mt-1 text-xs text-muted">{{ title(policy.lineBasis) }} · {{ title(policy.quantityBasis) }}<span v-if="policy.fixedQuantity"> {{ policy.fixedQuantity }}</span> · {{ policy.feeCode }}</p><p class="mt-1 text-xs text-muted">From {{ date(policy.effectiveFrom) }}</p></div><div class="flex gap-2"><UButton v-if="policy.status==='DRAFT'" label="Activate" size="xs" :loading="operatingId===policy.id" @click="movePolicy(policy,'activate')" /><UButton v-if="policy.status==='ACTIVE'" label="Retire" size="xs" color="neutral" variant="outline" @click="movePolicy(policy,'retire')" /></div></div><p v-if="!register.billingPolicies.length" class="p-6 text-center text-sm text-muted">No billing policies configured.</p></div></EmharePaginatedCollection></UCard>
      <UCard v-if="activeDataset==='invoices'" :ui="{body:'p-0'}"><div class="border-b border-muted p-4"><p class="text-xs uppercase text-primary">Posted receivables</p><h2 class="mt-1 text-lg font-semibold">Invoice register</h2></div><EmharePaginatedCollection v-slot="{ items: paginatedInvoices }" :items="register.invoices"><div class="divide-y divide-muted"><div v-for="invoice in paginatedInvoices" :key="invoice.id" class="p-4"><div class="flex items-start justify-between gap-3"><div><p class="font-mono text-xs text-primary">{{ invoice.invoiceNumber }}</p><p class="mt-1 font-medium">{{ invoice.studentNumber }} · {{ invoice.accountNumber }}</p><p class="mt-1 text-xs text-muted">{{ invoice.lines.length }} line{{ invoice.lines.length===1?'':'s' }} · due {{ date(invoice.dueDate) }}</p></div><div class="text-right"><p class="font-semibold">{{ money(invoice.grossTransactionAmount,invoice.transactionCurrencyCode) }}</p><p class="text-xs text-success">USD {{ money(invoice.grossBaseAmount) }}</p></div></div></div><p v-if="!register.invoices.length" class="p-6 text-center text-sm text-muted">No posted invoices.</p></div></EmharePaginatedCollection></UCard>
    </div></template>
  </UDashboardPanel>

  <EmhareRecordDrawer v-model:open="policyModalOpen" title="Create billing policy" description="Bind an authoritative event to an approved fee definition. A different Finance operator must activate the version."><template #body><div class="space-y-4"><div class="grid gap-4 sm:grid-cols-2"><UFormField label="Policy code" required><UInput v-model="policyForm.code" class="w-full" placeholder="REG-TUITION" /></UFormField><UFormField label="Policy name" required><UInput v-model="policyForm.name" class="w-full" placeholder="Registration tuition" /></UFormField></div><UFormField label="Source event type" required><UInput v-model="policyForm.sourceEventType" class="w-full" /></UFormField><UFormField label="Fee definition" required><USelect v-model="policyForm.feeCatalogueId" :items="catalogueItems" class="w-full" /></UFormField><div class="grid gap-4 sm:grid-cols-3"><UFormField label="Line basis" required><USelect v-model="policyForm.lineBasis" :items="lineBasisItems" class="w-full" /></UFormField><UFormField label="Quantity basis" required><USelect v-model="policyForm.quantityBasis" :items="quantityBasisItems" class="w-full" /></UFormField><UFormField v-if="policyForm.quantityBasis==='FIXED'" label="Fixed quantity" required><UInput v-model.number="policyForm.fixedQuantity" type="number" min="0.0001" step="0.0001" class="w-full" /></UFormField></div><div class="grid gap-4 sm:grid-cols-2"><UFormField label="Effective from" required><UInput v-model="policyForm.effectiveFrom" type="datetime-local" class="w-full" /></UFormField><UFormField label="Effective until"><UInput v-model="policyForm.effectiveUntil" type="datetime-local" class="w-full" /></UFormField></div></div></template><template #footer><div class="flex w-full justify-end gap-2"><UButton label="Cancel" color="neutral" variant="outline" @click="policyModalOpen=false" /><UButton label="Create draft policy" :loading="operatingId==='policy'" @click="createPolicy" /></div></template></EmhareRecordDrawer>
  <EmhareRecordDrawer v-model:open="invoiceModalOpen" title="Post invoice" description="The selected approved billing events will be copied into one immutable receivable document."><template #body><div class="space-y-4"><UAlert color="warning" variant="soft" title="Posting is irreversible" :description="`${selectedEvents.length} approved event(s), ${money(selectedTotal,selectedEvents[0]?.transactionCurrencyCode)} transaction total. Corrections require an independently posted credit note.`" /><div class="grid gap-4 sm:grid-cols-2"><UFormField label="Invoice date" required><UInput v-model="invoiceForm.invoiceDate" type="date" class="w-full" /></UFormField><UFormField label="Due date" required><UInput v-model="invoiceForm.dueDate" type="date" class="w-full" /></UFormField></div><UFormField label="Posting evidence" required><UTextarea v-model="invoiceForm.postingReason" :rows="4" class="w-full" placeholder="Record the batch control total and approval evidence." /></UFormField></div></template><template #footer><div class="flex w-full justify-end gap-2"><UButton label="Cancel" color="neutral" variant="outline" @click="invoiceModalOpen=false" /><UButton label="Post immutable invoice" icon="i-lucide-file-check-2" :loading="operatingId==='invoice'" @click="postInvoice" /></div></template></EmhareRecordDrawer>
</template>
